CREATE TABLE IF NOT EXISTS enterprise_quality_processes (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID REFERENCES workspaces(id) ON DELETE CASCADE, tenant_id UUID REFERENCES organizations(id) ON DELETE CASCADE, process_code TEXT NOT NULL, process_name TEXT NOT NULL, domain TEXT DEFAULT 'CORE_OPERATIONS', lifecycle_state TEXT DEFAULT 'ACTIVE', criticality TEXT DEFAULT 'BUSINESS_CRITICAL', owner_role TEXT NOT NULL, provenance_hash TEXT NOT NULL, created_at TIMESTAMPTZ DEFAULT NOW(), updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS enterprise_process_stages (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID REFERENCES workspaces(id) ON DELETE CASCADE, process_id UUID REFERENCES enterprise_quality_processes(id) ON DELETE CASCADE, stage_number INTEGER NOT NULL, stage_name TEXT NOT NULL, standard_duration_minutes NUMERIC(8,2) DEFAULT 45.0, created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS enterprise_process_performance (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID REFERENCES workspaces(id) ON DELETE CASCADE, process_id UUID REFERENCES enterprise_quality_processes(id) ON DELETE CASCADE, cycle_time_minutes NUMERIC(8,2) DEFAULT 42.5, throughput_per_hour NUMERIC(8,2) DEFAULT 14.2, first_pass_yield_pct NUMERIC(5,2) DEFAULT 98.4, recorded_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS enterprise_process_bottlenecks (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID REFERENCES workspaces(id) ON DELETE CASCADE, stage_id UUID REFERENCES enterprise_process_stages(id) ON DELETE CASCADE, bottleneck_type TEXT DEFAULT 'CAPACITY_CONSTRAINT', severity TEXT DEFAULT 'HIGH', queue_depth INTEGER DEFAULT 28, status TEXT DEFAULT 'CONFIRMED', detected_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS enterprise_process_quality (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID REFERENCES workspaces(id) ON DELETE CASCADE, process_id UUID REFERENCES enterprise_quality_processes(id) ON DELETE CASCADE, quality_score NUMERIC(5,2) DEFAULT 94.5, defect_density_pct NUMERIC(5,2) DEFAULT 0.8, evaluated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS enterprise_process_defects (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID REFERENCES workspaces(id) ON DELETE CASCADE, process_id UUID REFERENCES enterprise_quality_processes(id) ON DELETE CASCADE, defect_type TEXT NOT NULL, severity TEXT DEFAULT 'MEDIUM', containment_state TEXT DEFAULT 'CONTAINED', occurred_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS enterprise_process_root_causes (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID REFERENCES workspaces(id) ON DELETE CASCADE, defect_id UUID REFERENCES enterprise_process_defects(id) ON DELETE CASCADE, hypothesis TEXT NOT NULL, causal_confidence_score NUMERIC(5,2) DEFAULT 88.5, verification_status TEXT DEFAULT 'VERIFIED', analyzed_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS enterprise_process_conformance (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID REFERENCES workspaces(id) ON DELETE CASCADE, process_id UUID REFERENCES enterprise_quality_processes(id) ON DELETE CASCADE, conformance_rate_pct NUMERIC(5,2) DEFAULT 97.2, deviation_count INTEGER DEFAULT 3, evaluated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS enterprise_process_controls (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID REFERENCES workspaces(id) ON DELETE CASCADE, process_id UUID REFERENCES enterprise_quality_processes(id) ON DELETE CASCADE, control_code TEXT NOT NULL, control_name TEXT NOT NULL, effectiveness_score NUMERIC(5,2) DEFAULT 92.0, status TEXT DEFAULT 'ACTIVE', evaluated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS enterprise_process_capa (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID REFERENCES workspaces(id) ON DELETE CASCADE, root_cause_id UUID REFERENCES enterprise_process_root_causes(id) ON DELETE CASCADE, action_type TEXT DEFAULT 'CORRECTIVE', description TEXT NOT NULL, owner TEXT NOT NULL, status TEXT DEFAULT 'IMPLEMENTED', target_completion_date DATE NOT NULL, created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS enterprise_process_improvements (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID REFERENCES workspaces(id) ON DELETE CASCADE, process_id UUID REFERENCES enterprise_quality_processes(id) ON DELETE CASCADE, initiative_title TEXT NOT NULL, target_benefit_usd NUMERIC(14,2) DEFAULT 120000.00, lifecycle_stage TEXT DEFAULT 'IMPLEMENTED', created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS enterprise_process_waste (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID REFERENCES workspaces(id) ON DELETE CASCADE, process_id UUID REFERENCES enterprise_quality_processes(id) ON DELETE CASCADE, waste_category TEXT DEFAULT 'REWORK', estimated_cost_usd NUMERIC(12,2) DEFAULT 18500.00, detected_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS enterprise_process_dependencies (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID REFERENCES workspaces(id) ON DELETE CASCADE, upstream_process_id UUID REFERENCES enterprise_quality_processes(id) ON DELETE CASCADE, downstream_process_id UUID REFERENCES enterprise_quality_processes(id) ON DELETE CASCADE, dependency_type TEXT DEFAULT 'SEQUENTIAL', created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS enterprise_process_impacts (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID REFERENCES workspaces(id) ON DELETE CASCADE, process_id UUID REFERENCES enterprise_quality_processes(id) ON DELETE CASCADE, impact_domain TEXT DEFAULT 'CUSTOMER_DELIVERY', severity TEXT DEFAULT 'MEDIUM', evaluated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS enterprise_process_costs (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID REFERENCES workspaces(id) ON DELETE CASCADE, process_id UUID REFERENCES enterprise_quality_processes(id) ON DELETE CASCADE, cost_of_poor_quality_usd NUMERIC(14,2) DEFAULT 45000.00, calculated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS enterprise_process_automation (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID REFERENCES workspaces(id) ON DELETE CASCADE, process_id UUID REFERENCES enterprise_quality_processes(id) ON DELETE CASCADE, candidate_name TEXT NOT NULL, feasibility_score NUMERIC(5,2) DEFAULT 88.0, status TEXT DEFAULT 'AI_PROPOSED', evaluated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS enterprise_process_scenarios (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID REFERENCES workspaces(id) ON DELETE CASCADE, scenario_name TEXT NOT NULL, simulated_throughput_delta_pct NUMERIC(5,2) DEFAULT 22.5, status TEXT DEFAULT 'SIMULATED', created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS enterprise_process_forecasts (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID REFERENCES workspaces(id) ON DELETE CASCADE, forecast_horizon TEXT DEFAULT '12_MONTHS', projected_first_pass_yield_pct NUMERIC(5,2) DEFAULT 99.1, status TEXT DEFAULT 'FORECAST', confidence_score NUMERIC(5,2) DEFAULT 89.0, created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS enterprise_process_values (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID REFERENCES workspaces(id) ON DELETE CASCADE, projected_value_usd NUMERIC(14,2) NOT NULL, realized_value_usd NUMERIC(14,2) DEFAULT 0.00, variance_usd NUMERIC(14,2) DEFAULT 0.00, recorded_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS enterprise_process_drift (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID REFERENCES workspaces(id) ON DELETE CASCADE, entity_id UUID NOT NULL, drift_type TEXT NOT NULL, drift_level TEXT DEFAULT 'NO_DRIFT', detected_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS enterprise_process_learning (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID REFERENCES workspaces(id) ON DELETE CASCADE, event_type TEXT NOT NULL, description TEXT NOT NULL, append_only BOOLEAN DEFAULT true, created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS enterprise_process_recommendations (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID REFERENCES workspaces(id) ON DELETE CASCADE, recommendation_type TEXT NOT NULL, title TEXT NOT NULL, rationale TEXT NOT NULL, confidence_score NUMERIC(5,2) DEFAULT 88.0, status TEXT DEFAULT 'AI_PROPOSED', created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS enterprise_process_traces (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID REFERENCES workspaces(id) ON DELETE CASCADE, root_signal_id TEXT NOT NULL, trace_payload JSONB DEFAULT '{}'::jsonb, provenance_hash TEXT NOT NULL, generated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS enterprise_process_benchmarks (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID REFERENCES workspaces(id) ON DELETE CASCADE, benchmark_name TEXT NOT NULL, industry_average_cycle_time_minutes NUMERIC(8,2) DEFAULT 55.0, recorded_at TIMESTAMPTZ DEFAULT NOW());
